CREATE TABLE users(id INTEGER PRIMARY KEY, username TEXT NOT NULL COLLATE NOCASE UNIQUE, password TEXT NOT NULL, owner INTEGER NOT NULL, admin INTEGER NOT NULL, epoch INTEGER NOT NULL DEFAULT 0);
CREATE TABLE sessions(token TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires INTEGER NOT NULL);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE limits(bucket TEXT PRIMARY KEY, count INTEGER NOT NULL, until INTEGER NOT NULL);
CREATE TABLE entries(user_id INTEGER NOT NULL REFERENCES users(id), kind TEXT NOT NULL, id TEXT NOT NULL, version INTEGER NOT NULL, body TEXT NOT NULL, updated TEXT NOT NULL, PRIMARY KEY(user_id,kind,id));
CREATE TABLE audit(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), at TEXT NOT NULL, action TEXT NOT NULL, detail TEXT NOT NULL);
CREATE INDEX audit_user ON audit(user_id,id);
CREATE TABLE public_calendar(date TEXT PRIMARY KEY, version INTEGER NOT NULL, body TEXT NOT NULL, updated TEXT NOT NULL);
